public static bool IsPalindrome(string s)
{
    if (s == null) return false;
    if (s.Length == 0) return true;

    int left = 0;
    int right = s.Length - 1;

    while (left < right)
    {
        char leftChar = s[left];
        bool leftIsAlphanumeric = char.IsLetterOrDigit(leftChar);

        if (!leftIsAlphanumeric)
        {
            left++;
            continue;
        }

        char rightChar = s[right];
        bool rightIsAlphanumeric = char.IsLetterOrDigit(rightChar);

        if (!rightIsAlphanumeric)
        {
            right--;
            continue;
        }

        if (char.ToLowerInvariant(leftChar) != char.ToLowerInvariant(rightChar))
        {
            return false;
        }

        left++;
        right--;
    }

    return true;
}
