using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static int[] TopKFrequent(int[] nums, int k)
    {
        // Use a Dictionary to count frequencies
        Dictionary<int, int> counts = new Dictionary<int, int>();
        foreach (int num in nums)
        {
            if (counts.ContainsKey(num))
                counts[num]++;
            else
                counts[num] = 1;
        }

        // Convert to a list of KeyValuePairs for sorting
        List<KeyValuePair<int, int>> list = new List<KeyValuePair<int, int>>(counts);

        // Sort: Primary key is Frequency (Descending), Secondary key is Value (Ascending)
        list.Sort(delegate(KeyValuePair<int, int> x, KeyValuePair<int, int> y)
        {
            if (x.Value != y.Value)
            {
                return y.Value.CompareTo(x.Value); // Higher frequency first
            }
            return x.Key.CompareTo(y.Key); // Smaller value on tie
        });

        // Extract the top k keys
        int[] result = new int[k];
        for (int i = 0; i < k; i++)
        {
            result[i] = list[i].Key;
        }

        return result;
    }
}
