public static int FirstIndexOf(int[] sorted, int target)
{
    if (sorted == null || sorted.Length == 0)
    {
        return -1;
    }

    int low = 0;
    int high = sorted.Length - 1;
    int result = -1;

    while (low <= high)
    {
        // Prevent overflow compared to (low + high) / 2
        int mid = low + ((high - low) >> 1);

        if (sorted[mid] == target)
        {
            result = mid;
            // Continue searching left to find the first occurrence
            high = mid - 1;
        }
        else if (sorted[mid] < target)
        {
            low = mid + 1;
        }
        else
        {
            high = mid - 1;
        }
    }

    return result;
}
