        // e.g., "userId" -> "user_Id", "version2Update" -> "version2_Update"
        string result = Regex.Replace(name, @"([a-z0-9])([A-Z])", "$1_$2");

        // Step 2: Insert underscore between an uppercase letter and the start of a new word (Upper + Lower).
        // This handles acronyms followed by a word.
        // e.g., "HTTPResponse" -> "HTTP_Response"
        result = Regex.Replace(result, @"([A-Z])([A-Z][a-z])", "$1_$2");

